#include <zlib.h>
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <string>
#include <vector>
using namespace std;
static constexpr uint32_t SCALE=12, TOT=1u<<SCALE, RANS_L=1u<<23;
static void p16(vector<uint8_t>&o,uint16_t v){o.push_back(v);o.push_back(v>>8);} static void p32(vector<uint8_t>&o,uint32_t v){for(int i=0;i<4;i++)o.push_back(uint8_t(v>>(8*i)));} static void p64(vector<uint8_t>&o,uint64_t v){for(int i=0;i<8;i++)o.push_back(uint8_t(v>>(8*i)));}
static uint16_t g16(const vector<uint8_t>&x,size_t&p){if(p+2>x.size())throw runtime_error("truncated u16");uint16_t v=x[p]|uint16_t(x[p+1])<<8;p+=2;return v;} static uint32_t g32(const vector<uint8_t>&x,size_t&p){if(p+4>x.size())throw runtime_error("truncated u32");uint32_t v=0;for(int i=0;i<4;i++)v|=uint32_t(x[p++])<<(8*i);return v;} static uint64_t g64(const vector<uint8_t>&x,size_t&p){if(p+8>x.size())throw runtime_error("truncated u64");uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(x[p++])<<(8*i);return v;}
static uint32_t crc(const uint8_t*p,size_t n){return ::crc32(0L,p,(uInt)n);} static vector<uint8_t> deflate_block(const vector<uint8_t>&a,int level){uLongf cap=compressBound((uLong)a.size());vector<uint8_t>b(cap);int r=compress2(b.data(),&cap,a.data(),(uLong)a.size(),level);if(r!=Z_OK)throw runtime_error("deflate failed");b.resize(cap);return b;}
static vector<uint8_t> delta(const vector<uint8_t>&a){vector<uint8_t>b(a.size());if(a.empty())return b;b[0]=a[0];for(size_t i=1;i<a.size();i++)b[i]=uint8_t(a[i]-a[i-1]);return b;} static vector<uint8_t> undelta(const vector<uint8_t>&a){vector<uint8_t>b(a.size());if(a.empty())return b;b[0]=a[0];for(size_t i=1;i<a.size();i++)b[i]=uint8_t(b[i-1]+a[i]);return b;}
static vector<uint8_t> rle(const vector<uint8_t>&a){vector<uint8_t>b;for(size_t i=0;i<a.size();){size_t j=i+1;while(j<a.size()&&a[j]==a[i]&&j-i<256)j++;b.push_back(uint8_t(j-i-1));b.push_back(a[i]);i=j;}return b;} static vector<uint8_t> unrle(const vector<uint8_t>&a,size_t n){if(a.size()%2)throw runtime_error("bad RLE length");vector<uint8_t>b;b.reserve(n);for(size_t i=0;i<a.size();i+=2){size_t k=size_t(a[i])+1;if(b.size()+k>n)throw runtime_error("RLE overflow");b.insert(b.end(),k,a[i+1]);}if(b.size()!=n)throw runtime_error("RLE size mismatch");return b;}
struct Model{array<uint16_t,256> f{};array<uint16_t,256> c{};array<uint8_t,TOT> dec{};};
static Model make_model(const vector<uint8_t>&a){Model m;array<uint64_t,256> cnt{};for(uint8_t b:a)cnt[b]++;uint64_t n=a.size();uint32_t sum=0;array<uint64_t,256> rem{};for(int i=0;i<256;i++)if(cnt[i]){uint64_t scaled=cnt[i]*(TOT-256)/n;m.f[i]=uint16_t(1+scaled);rem[i]=(cnt[i]*(TOT-256))%n;sum+=m.f[i];}while(sum<TOT){int best=-1;for(int i=0;i<256;i++)if(cnt[i]&&(best<0||rem[i]>rem[best]))best=i;if(best<0)throw runtime_error("model normalization");m.f[best]++;rem[best]=0;sum++;}while(sum>TOT){int best=-1;for(int i=0;i<256;i++)if(m.f[i]>1&&(best<0||rem[i]<rem[best]))best=i;if(best<0)throw runtime_error("model overflow");m.f[best]--;sum--;}
 uint32_t cur=0;for(int i=0;i<256;i++){m.c[i]=uint16_t(cur);for(uint32_t k=0;k<m.f[i];k++)m.dec[cur+k]=uint8_t(i);cur+=m.f[i];}return m;}
static vector<uint8_t> rans_encode(const vector<uint8_t>&a){if(a.empty())return {};Model m=make_model(a);uint32_t state=RANS_L;vector<uint8_t> ren;for(size_t z=a.size();z-->0;){uint8_t s=a[z];uint32_t f=m.f[s],c=m.c[s];uint32_t xmax=((RANS_L>>SCALE)<<8)*f;while(state>=xmax){ren.push_back(uint8_t(state));state>>=8;}state=((state/f)<<SCALE)+(state%f)+c;}vector<uint8_t> out;for(int i=0;i<256;i++)p16(out,m.f[i]);p32(out,state);for(auto it=ren.rbegin();it!=ren.rend();++it)out.push_back(*it);return out;}
static vector<uint8_t> rans_decode(const vector<uint8_t>&in,size_t n){if(n==0){if(!in.empty())throw runtime_error("nonempty rANS empty payload");return {};}if(in.size()<516)throw runtime_error("short rANS payload");size_t p=0;Model m;uint32_t sum=0;for(int i=0;i<256;i++){m.f[i]=g16(in,p);if(m.f[i]>TOT)throw runtime_error("bad rANS frequency");m.c[i]=uint16_t(sum);sum+=m.f[i];}if(sum!=TOT)throw runtime_error("bad rANS model sum");uint32_t cur=0;for(int i=0;i<256;i++){for(uint32_t k=0;k<m.f[i];k++)m.dec[cur++]=uint8_t(i);}uint32_t state=g32(in,p);if(state<RANS_L)throw runtime_error("bad rANS state");vector<uint8_t> out;out.reserve(n);for(size_t i=0;i<n;i++){uint32_t slot=state&(TOT-1);uint8_t s=m.dec[slot];uint32_t f=m.f[s],c=m.c[s];if(!f)throw runtime_error("zero rANS frequency");state=f*(state>>SCALE)+(slot-c);while(state<RANS_L){if(p>=in.size())throw runtime_error("truncated rANS stream");state=(state<<8)|in[p++];}out.push_back(s);}if(p!=in.size())throw runtime_error("rANS trailing bytes");return out;}
static vector<uint8_t> context_predict(const vector<uint8_t>&a, array<uint8_t,256>&pred){
 array<array<uint32_t,256>,256> cnt{};
 for(size_t i=0;i<a.size();i++){uint8_t ctx=(i? a[i-1]:0);cnt[ctx][a[i]]++;}
 for(int c=0;c<256;c++){uint32_t best=0;uint8_t sym=0;for(int b=0;b<256;b++)if(cnt[c][b]>best){best=cnt[c][b];sym=uint8_t(b);}pred[c]=sym;}
 vector<uint8_t> r(a.size());for(size_t i=0;i<a.size();i++){uint8_t ctx=i?a[i-1]:0;r[i]=uint8_t(a[i]^pred[ctx]);}return r;
}
static vector<uint8_t> context_encode(const vector<uint8_t>&a){array<uint8_t,256> pred{};auto residual=context_predict(a,pred);auto coded=rans_encode(residual);vector<uint8_t> out(pred.begin(),pred.end());out.insert(out.end(),coded.begin(),coded.end());return out;}
static vector<uint8_t> context_decode(const vector<uint8_t>&in,size_t n){if(in.size()<256)throw runtime_error("short context model");array<uint8_t,256> pred{};copy_n(in.begin(),256,pred.begin());vector<uint8_t> q(in.begin()+256,in.end());auto r=rans_decode(q,n);vector<uint8_t> out(n);for(size_t i=0;i<n;i++){uint8_t ctx=i?out[i-1]:0;out[i]=uint8_t(r[i]^pred[ctx]);}return out;}
static vector<uint8_t> stride_delta(const vector<uint8_t>&a,size_t stride){vector<uint8_t>b(a.size());for(size_t i=0;i<a.size();i++)b[i]=uint8_t(a[i]-(i>=stride?a[i-stride]:0));return b;}
// STN7 header 20 bytes. Modes: 0 RAW,1 RLE,2 DEFLATE,3 DELTA1+DEFLATE,4 rANS,5 DELTA1+rANS,6 context-XOR+rANS,7 DELTA2+rANS,8 DELTA4+rANS.
static vector<uint8_t> encode(const vector<uint8_t>&in,int level,size_t bs){if(level<1||level>9||bs<1024||bs>4*1024*1024)throw runtime_error("invalid level/block size");vector<uint8_t>o={'S','T','N','7',1,0,0,0};p64(o,in.size());uint32_t blocks=uint32_t((in.size()+bs-1)/bs);p32(o,blocks);for(size_t off=0;off<in.size();off+=bs){size_t n=min(bs,in.size()-off);vector<uint8_t>a(in.begin()+off,in.begin()+off+n),best=a;uint8_t mode=0;auto test=[&](uint8_t m,vector<uint8_t>&&v){if(v.size()<best.size()){best=move(v);mode=m;}};test(1,rle(a));test(2,deflate_block(a,level));auto d=delta(a);test(3,deflate_block(d,level));test(4,rans_encode(a));test(5,rans_encode(d));test(6,context_encode(a));test(7,rans_encode(stride_delta(a,2)));test(8,rans_encode(stride_delta(a,4)));o.push_back(mode);p32(o,uint32_t(n));p32(o,uint32_t(best.size()));p32(o,crc(a.data(),a.size()));o.insert(o.end(),best.begin(),best.end());}return o;}
static vector<uint8_t> decode(const vector<uint8_t>&x){if(x.size()<20||memcmp(x.data(),"STN7",4))throw runtime_error("bad STN7 header");size_t p=4;if(x[p++]!=1||x[p++]||x[p++]||x[p++])throw runtime_error("unsupported flags");uint64_t total=g64(x,p);uint32_t count=g32(x,p);if(total>(1ull<<34)||count>10000000)throw runtime_error("size limit");vector<uint8_t>out;out.reserve(size_t(total));for(uint32_t bi=0;bi<count;bi++){if(p>=x.size())throw runtime_error("truncated block");uint8_t mode=x[p++];uint32_t raw=g32(x,p),plen=g32(x,p),sum=g32(x,p);if(raw>4*1024*1024||plen>x.size()-p||out.size()+raw>total)throw runtime_error("bad block bounds");vector<uint8_t>q(x.begin()+p,x.begin()+p+plen);p+=plen;vector<uint8_t>b;if(mode==0){if(plen!=raw)throw runtime_error("raw size mismatch");b=move(q);}else if(mode==1)b=unrle(q,raw);else if(mode==2||mode==3){b.resize(raw);uLongf z=raw;int r=uncompress(b.data(),&z,q.data(),plen);if(r!=Z_OK||z!=raw)throw runtime_error("inflate failed");if(mode==3)b=undelta(b);}else if(mode==4||mode==5||mode==7||mode==8){b=rans_decode(q,raw);if(mode==5)b=undelta(b);else if(mode==7||mode==8){size_t stride=mode==7?2:4;for(size_t i=0;i<b.size();i++)b[i]=uint8_t(b[i]+(i>=stride?b[i-stride]:0));}}else if(mode==6)b=context_decode(q,raw);else throw runtime_error("unknown mode");if(crc(b.data(),b.size())!=sum)throw runtime_error("block CRC mismatch");out.insert(out.end(),b.begin(),b.end());}if(p!=x.size()||out.size()!=total)throw runtime_error("container size/trailing data mismatch");return out;}
int main(int argc,char**argv){try{if(argc<4){cerr<<"usage: steno_hybrid encode|decode input output [level=6] [block=1048576]\n";return 2;}ifstream f(argv[2],ios::binary);if(!f)throw runtime_error("input open failed");vector<uint8_t>in((istreambuf_iterator<char>(f)),{});auto t=chrono::steady_clock::now();vector<uint8_t>out;if(string(argv[1])=="encode")out=encode(in,argc>4?stoi(argv[4]):6,argc>5?stoull(argv[5]):1048576);else if(string(argv[1])=="decode")out=decode(in);else throw runtime_error("unknown mode");auto e=chrono::steady_clock::now();ofstream g(argv[3],ios::binary);g.write((char*)out.data(),out.size());if(!g)throw runtime_error("output write failed");double sec=chrono::duration<double>(e-t).count();cerr<<"input="<<in.size()<<" output="<<out.size()<<" seconds="<<sec<<" MiB_s="<<(sec?in.size()/1048576.0/sec:0)<<"\n";return 0;}catch(const exception&e){cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
